sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var count = new GlideAggregate("x_1397649_quiz_app_question");
    count.addAggregate("COUNT");
    count.query();
    if (count.next()) {
        var questionCount = parseInt(count.getAggregate("COUNT"), 10);
        if (questionCount >= 16 && getOpenCount() === 0) {
            createMaintenance();
			gs.addInfoMessage("Quesiton maintenace task created");
        }
    }


    function createMaintenance() {
        var maintenance = new GlideRecord("x_1397649_quiz_app_quiz_maintenance");
        maintenance.initialize();
        maintenance.setValue("short_description", "Quiz questions maintenance required");
        maintenance.setValue("assignment_group", "8cce7666c357321034d93d0ed4013109");
        maintenance.setValue("state", 1);
        maintenance.insert();
    }

    function getOpenCount() {
        var openCount = new GlideAggregate("x_1397649_quiz_app_quiz_maintenance");
        openCount.addQuery("state", 1);
        openCount.addAggregate("COUNT");
        openCount.query();
        if (openCount.next()) {
            return parseInt(openCount.getAggregate("COUNT"), 10);
        }
		return 0;
    }

})(current, previous);
